const invoices = $('QuickBooks - Unpaid Invoices').all();
// Pipedrive v1 returns one item holding a data array of organisations.
const orgs = $('Pipedrive - Customer Context').all()
  .flatMap(i => Array.isArray((i.json || {}).data) ? i.json.data.map(o => ({ json: o })) : [i]);
const stateRows = $('Postgres - Load Collection State').all();
const qbCustomers = $('QuickBooks - Customers').all();

const DAY = 86400000;
const today = new Date();
today.setHours(0, 0, 0, 0);

function toDate(v) {
  if (!v) return null;
  const m = String(v).match(/\/Date\((\d+)/);
  const d = m ? new Date(Number(m[1])) : new Date(v);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}
function dayDiff(a, b) { return Math.round((a.getTime() - b.getTime()) / DAY); }
function iso(d) { return d ? d.toISOString().slice(0, 10) : null; }
function addDays(d, n) { return new Date(d.getTime() + n * DAY); }

// Minimum days between contacts, per stage. Chasing daily is how you get
// marked as spam and lose the relationship.
const CADENCE = { pre_due: 0, due: 0, od_1_7: 3, od_8_14: 3, od_15_30: 5, od_30_plus: 7 };

const orgByName = {};
for (const o of orgs) {
  const n = String((o.json || {}).name || '').trim().toLowerCase();
  if (n) orgByName[n] = o.json;
}

// Billing email comes from QuickBooks - Pipedrive organisations have no email
// field. Order: an address saved in Postgres (from a wrong-contact reply), then
// the customer's primary email (the maintained contact record), then the
// invoice's billing email, which is only a copy taken when the invoice was made.
const emailByContactId = {};
for (const c of qbCustomers) {
  const x = c.json || {};
  const addr = (x.PrimaryEmailAddr || {}).Address;
  if (x.Id && addr) emailByContactId[String(x.Id)] = String(addr).trim();
}

const stateById = {};
for (const r of stateRows) {
  const s = r.json || {};
  if (s.invoice_id) stateById[s.invoice_id] = s;
}

const out = [];
const seen = {};

for (const item of invoices) {
  const inv = item.json || {};
  const invoiceId = inv.Id ? String(inv.Id) : '';
  if (!invoiceId) continue;
  // All invoices are fetched, so paid and voided ones arrive here too. Leave
  // them out of 'seen' so the close-paid step below closes them in Postgres.
  const amountDue = Number(inv.Balance || 0);
  if (amountDue <= 0) continue;
  seen[invoiceId] = true;

  const due = toDate(inv.DueDate);
  if (!due) continue;

  const daysOverdue = dayDiff(today, due);
  let stage;
  if (daysOverdue < 0) stage = 'pre_due';
  else if (daysOverdue === 0) stage = 'due';
  else if (daysOverdue <= 7) stage = 'od_1_7';
  else if (daysOverdue <= 14) stage = 'od_8_14';
  else if (daysOverdue <= 30) stage = 'od_15_30';
  else stage = 'od_30_plus';

  const st = stateById[invoiceId] || {};
  const customerRef = inv.CustomerRef || {};
  const customerName = String(customerRef.name || '');
  const org = orgByName[customerName.trim().toLowerCase()] || {};

  // ---- HARD STOPS ----
  // A disputed invoice is never chased. Chasing a customer who has raised a
  // dispute is how an AR process destroys an account.
  if (String(st.dispute_status || 'none') === 'open') continue;
  if (st.collection_stage === 'wrong_contact') continue;
  // Only one final notice. After it goes out the account owner takes over
  // (Pipedrive task); reminders restart only if someone changes the stage.
  if (st.collection_stage === 'final_notice_sent') continue;
  const nextAction = toDate(st.next_action_date);
  if (nextAction && nextAction > today) continue;

  // ---- PROMISE TO PAY ----
  const promise = toDate(st.promise_to_pay_date);
  let promiseBroken = false;
  if (promise) {
    if (promise >= today) continue;
    promiseBroken = true;
  }

  // ---- CADENCE ----
  const lastContacted = toDate(st.last_contacted);
  const minGap = CADENCE[stage] || 3;
  if (!promiseBroken && lastContacted && dayDiff(today, lastContacted) < minGap) continue;

  // Pre-due is a single courtesy note 3 days out, never a repeated nag.
  if (stage === 'pre_due') {
    if (daysOverdue !== -3) continue;
    if (lastContacted) continue;
  }

  const ownerObj = org.owner_id || {};
  const timesContacted = Number(st.times_contacted || 0);
  const contactEmail = st.contact_email || emailByContactId[String(customerRef.value || '')] || String((inv.BillEmail || {}).Address || '').trim() || '';

  // No address means no email. Send it to a human instead of handing Gmail an
  // empty recipient and failing the whole branch.
  let action = 'chase';
  if (!contactEmail) action = 'no_contact';
  else if (stage === 'od_30_plus') action = 'final_notice';
  else if (stage === 'pre_due' || stage === 'due') action = 'courtesy';

  const subjectTail = daysOverdue > 0
    ? ' is ' + daysOverdue + ' days overdue'
    : (daysOverdue === 0 ? ' is due today' : ' falls due on ' + iso(due));

  out.push({
    json: {
      action: action,
      invoiceId: invoiceId,
      invoiceNumber: inv.DocNumber || '',
      customerId: String(customerRef.value || ''),
      customerName: customerName,
      contactEmail: contactEmail,
      currency: (inv.CurrencyRef || {}).value || 'USD',
      amountDue: amountDue,
      invoiceTotal: Number(inv.TotalAmt || 0),
      reference: (inv.CustomerMemo || {}).value || inv.PrivateNote || '',
      dueDate: iso(due),
      daysOverdue: daysOverdue,
      collectionStage: stage,
      promiseBroken: promiseBroken,
      promiseDate: iso(promise),
      lastContacted: iso(lastContacted),
      timesContacted: timesContacted,
      timesContactedNext: timesContacted + 1,
      nextActionDate: iso(addDays(today, minGap || 3)),
      accountOwner: ownerObj.name || st.assigned_owner || 'unassigned',
      ownerEmail: ownerObj.email || '',
      customerStatus: org.label || 'unknown',
      pipedriveOrgId: org.id || null,
      openDealsCount: Number(org.open_deals_count || 0),
      emailSubject: 'TalentBridge Staffing - invoice ' + (inv.DocNumber || '') + subjectTail
    }
  });
}

// ---- CLOSE PAID ----
// Anything open in Postgres that QuickBooks no longer reports as unpaid has
// been paid. Closing it here is what stops a paid invoice being chased.
for (const r of stateRows) {
  const s = r.json || {};
  if (!s.invoice_id) continue;
  if (seen[s.invoice_id]) continue;
  out.push({
    json: {
      action: 'close_paid',
      invoiceId: s.invoice_id,
      invoiceNumber: s.invoice_number || '',
      customerName: s.customer_name || '',
      customerId: s.customer_id || '',
      contactEmail: s.contact_email || '',
      collectionStage: 'closed',
      daysOverdue: 0,
      amountDue: 0,
      currency: 'USD',
      timesContactedNext: Number(s.times_contacted || 0),
      accountOwner: s.assigned_owner || 'unassigned',
      customerStatus: 'paid',
      emailSubject: ''
    }
  });
}

return out;

